/**
 * 🎨 主题上下文
 * 
 * 功能：
 * - 主题切换管理
 * - 系统主题检测
 * - 主题持久化
 * - 主题相关工具函数
 */

import React, { createContext, useContext, useEffect, useState } from 'react';
import { globalDataManager } from '@/services/unifiedDataManager';
import { userSettingsService } from '@/services/userSettingsService';
import { useAuth } from '@/hooks/useAuth';

export type Theme = 'light' | 'dark' | 'system';

interface ThemeContextType {
  theme: Theme;
  setTheme: (theme: Theme) => void;
  actualTheme: 'light' | 'dark';
}

const ThemeContext = createContext<ThemeContextType | undefined>(undefined);

/**
 * 获取系统主题
 */
function getSystemTheme(): 'light' | 'dark' {
  if (typeof window === 'undefined') return 'light';
  return window.matchMedia('(prefers-color-scheme: dark)').matches ? 'dark' : 'light';
}

/**
 * 从用户设置服务获取保存的主题
 */
async function getSavedTheme(): Promise<Theme> {
  if (typeof window === 'undefined') return 'system';
  try {
    // 优先从用户设置服务获取
    const mode = await userSettingsService.getThemeMode();
    if (mode && ['light', 'dark', 'system'].includes(mode)) {
      return mode;
    }

    // 兜底1：从统一数据管理器获取
    const saved = await globalDataManager.getData<Theme>('theme');
    if (saved && ['light', 'dark', 'system'].includes(saved)) {
      return saved;
    }

    // 兜底2：从localStorage获取
    const fallback = localStorage.getItem('theme') as Theme;
    return fallback && ['light', 'dark', 'system'].includes(fallback) ? fallback : 'system';
  } catch {
    return 'system';
  }
}

/**
 * 保存主题到用户设置服务
 */
async function saveTheme(theme: Theme): Promise<void> {
  if (typeof window === 'undefined') return;
  try {
    // 优先保存到用户设置服务（会自动处理云端同步）
    await userSettingsService.saveThemeMode(theme);

    // 同时保存到统一数据管理器以保持兼容性
    await globalDataManager.setData('theme', theme);
  } catch (error) {
    console.warn('保存主题设置失败:', error);
    // 兜底：保存到localStorage
    try {
      localStorage.setItem('theme', theme);
    } catch {
      // 忽略存储错误
    }
  }
}

/**
 * 应用主题到DOM
 */
function applyTheme(actualTheme: 'light' | 'dark'): void {
  if (typeof window === 'undefined') return;

  const root = window.document.documentElement;
  root.classList.remove('light', 'dark');
  root.classList.add(actualTheme);

  // 设置CSS变量
  if (actualTheme === 'dark') {
    root.style.colorScheme = 'dark';
  } else {
    root.style.colorScheme = 'light';
  }
}

/**
 * 主题提供者组件
 */
export function ThemeProvider({ children }: { children: React.ReactNode }) {
  const [theme, setThemeState] = useState<Theme>('system');
  const [actualTheme, setActualTheme] = useState<'light' | 'dark'>('light');
  const { user } = useAuth();

  // 初始化主题和响应用户变化
  useEffect(() => {
    const initTheme = async () => {
      try {
        // 如果用户已登录，初始化用户设置服务
        if (user?.id) {
          userSettingsService.setUserId(user.id);
        }

        const savedTheme = await getSavedTheme();
        setThemeState(savedTheme);
      } catch (error) {
        console.error('主题初始化失败:', error);
        setThemeState('system');
      }
    };

    initTheme();
  }, [user?.id]); // 依赖用户ID，用户变化时重新初始化

  // 监听系统主题变化
  useEffect(() => {
    if (typeof window === 'undefined') return;

    const mediaQuery = window.matchMedia('(prefers-color-scheme: dark)');

    const handleChange = () => {
      if (theme === 'system') {
        const systemTheme = getSystemTheme();
        setActualTheme(systemTheme);
        applyTheme(systemTheme);
      }
    };

    mediaQuery.addEventListener('change', handleChange);
    return () => mediaQuery.removeEventListener('change', handleChange);
  }, [theme]);

  // 计算实际主题
  useEffect(() => {
    let newActualTheme: 'light' | 'dark';

    if (theme === 'system') {
      newActualTheme = getSystemTheme();
    } else {
      newActualTheme = theme;
    }

    setActualTheme(newActualTheme);
    applyTheme(newActualTheme);
  }, [theme]);

  const setTheme = (newTheme: Theme) => {
    setThemeState(newTheme);
    // 异步保存主题，不阻塞UI更新
    saveTheme(newTheme).catch(error => {
      console.error('保存主题失败:', error);
    });
  };

  const value: ThemeContextType = {
    theme,
    setTheme,
    actualTheme
  };

  return (
    <ThemeContext.Provider value={value}>
      {children}
    </ThemeContext.Provider>
  );
}

/**
 * 使用主题Hook
 */
export function useTheme() {
  const context = useContext(ThemeContext);

  if (context === undefined) {
    throw new Error('useTheme must be used within a ThemeProvider');
  }

  return context;
}

/**
 * 主题工具函数
 */
export const themeUtils = {
  /**
   * 获取当前系统主题
   */
  getSystemTheme,

  /**
   * 检查是否为暗色主题
   */
  isDark: (theme: Theme): boolean => {
    if (theme === 'system') {
      return getSystemTheme() === 'dark';
    }
    return theme === 'dark';
  },

  /**
   * 获取主题显示名称
   */
  getThemeDisplayName: (theme: Theme): string => {
    const names = {
      light: '浅色',
      dark: '深色',
      system: '跟随系统'
    };
    return names[theme];
  },

  /**
   * 获取主题图标
   */
  getThemeIcon: (theme: Theme): string => {
    const icons = {
      light: '☀️',
      dark: '🌙',
      system: '💻'
    };
    return icons[theme];
  }
};

